base.src/core.js:
// The core holds at most CORE_POSTS terrain posts in all. Past it an allocation traps, the core
// restarts, and every loaded terrain is dropped. loadedPosts(core) is how many it holds now.
export const CORE_POSTS = 48e6;

export function loadedPosts(core) {
  return core.terrains.reduce((sum, t) => sum + t.posts, 0);
}

base.src/terrain-load.js:
import { CORE_POSTS } from './core.js';

// The step that fits a DEM in the core.
export function loadStep(dem) {
  let step = 1;
  while (Math.ceil(dem.width / step) * Math.ceil(dem.height / step) > CORE_POSTS) step += 1;
  return step;
}

export function loadTerrain(core, dem) {
  return core.addTerrain(dem, loadStep(dem));
}

head.src/terrain-load.js:
import { CORE_POSTS, loadedPosts } from './core.js';

// The step that fits a DEM in the room the loaded terrains leave in the core.
export function loadStep(dem, used = 0) {
  const room = CORE_POSTS - used;
  if (room < 1) throw new Error('The loaded terrains fill the core; remove one to load ' + dem.name);
  let step = 1;
  while (Math.ceil(dem.width / step) * Math.ceil(dem.height / step) > room) step += 1;
  return step;
}

export function loadTerrain(core, dem) {
  return core.addTerrain(dem, loadStep(dem, loadedPosts(core)));
}

head.tests/terrain-load.test.js:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { loadStep } from '../src/terrain-load.js';

const tile = { name: 'n39w106', width: 3601, height: 3601 };

test('a tile loads whole into an empty core', () => {
  assert.equal(loadStep(tile, 0), 1);
});

test('a tile that no longer fits whole is thinned to the room that is left', () => {
  const step = loadStep(tile, 40e6);
  assert.equal(step, 2);
  assert.ok(Math.ceil(3601 / step) ** 2 <= 8e6);
});

test('a full core refuses by name', () => {
  assert.throws(() => loadStep(tile, 48e6), /fill the core/);
});
